document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("water-usage-form"),n=document.getElementById("water-usage-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("garden-area").value),r=document.getElementById("garden-type").value,o=document.getElementById("climate-zone").value,a=document.getElementById("soil-type").value,s=parseFloat(document.getElementById("mulch-coverage").value),i=document.getElementById("irrigation-method").value,p=parseFloat(document.getElementById("rainfall").value),l=parseFloat(document.getElementById("water-cost").value),d=document.getElementById("analysis-period").value;if(t<=0||!r||!o||!a||!i)return n.textContent="Please fill in all required fields.",void 0;const[g,c]=r.split(","),[u,m]=o.split(","),[h,v]=a.split(","),[f,w]=i.split(","),y=parseFloat(c),$=parseFloat(m),F=parseFloat(v),x=parseFloat(w),k=.005*s,M=y*$*F*(1-k),E=.623*t,I=Math.max(0,M-p),b=I*E,W=b/x,B={week:1,month:4.33,season:26,year:52}[d],C=W*B,q=C/1e3*l,R=Math.min(.9,x+.1),S=Math.min(100,s+25),A=y*$*F*(1-.005*S),D=(W-Math.max(0,A-p)*E/R)*B,P=D/1e3*l,H=2*t,L=H*(p/12)*.623*B,T=L/1e3*l,j=.002*C;var U,z;n.innerHTML=`\n        <div class="result-section">\n          <h4>Garden Water Analysis (${d}):</h4>\n          <p>Garden: ${t.toLocaleString()} sq ft ${g}</p>\n          <p>Climate: ${u} conditions</p>\n          <p>Soil: ${h}</p>\n          <p>Irrigation: ${f} (${(100*x).toFixed(0)}% efficient)</p>\n          <p>Mulch coverage: ${s}%</p>\n        </div>\n        \n        <div class="result-water-needs">\n          <h4>Water Requirements:</h4>\n          <p><strong>Base water need:</strong> ${y}" per week</p>\n          <p><strong>Adjusted for conditions:</strong> ${M.toFixed(2)}" per week</p>\n          <p><strong>After rainfall:</strong> ${I.toFixed(2)}" irrigation needed</p>\n          <p><strong>Weekly irrigation:</strong> ${b.toFixed(0)} gallons needed</p>\n          <p><strong>With efficiency loss:</strong> ${W.toFixed(0)} gallons applied</p>\n        </div>\n        \n        <div class="result-usage">\n          <h4>Total Water Usage:</h4>\n          <p><strong>${C.toFixed(0)} gallons</strong> for ${d}</p>\n          <p>Daily average: ${(C/(7*B)).toFixed(1)} gallons</p>\n          <p>Per square foot: ${(C/t).toFixed(2)} gallons</p>\n          <p><strong>Total cost: $${q.toFixed(2)}</strong></p>\n          <p>Cost per sq ft: $${(q/t).toFixed(3)}</p>\n        </div>\n        \n        <div class="result-efficiency">\n          <h4>Efficiency Analysis:</h4>\n          <p>Water wasted: ${(100*(1-x)).toFixed(0)}% (${((W-b)*B).toFixed(0)} gallons)</p>\n          <p>Mulch water savings: ${(100*k).toFixed(1)}%</p>\n          <p>Rainfall contribution: ${p>0?`${(p/M*100).toFixed(0)}%`:"None this period"}</p>\n          <p>Irrigation efficiency: ${f} performs ${x>=.85?"excellent":x>=.75?"good":"needs improvement"}</p>\n        </div>\n        \n        <div class="result-improvements">\n          <h4>Potential Improvements:</h4>\n          <p><strong>Water savings:</strong> ${D.toFixed(0)} gallons ${d}</p>\n          <p><strong>Cost savings:</strong> $${P.toFixed(2)} ${d}</p>\n          <p>Better irrigation: Upgrade to ${x<.85?"drip system":"more efficient timers"}</p>\n          <p>More mulch: Increase coverage to ${S}%</p>\n          <p>Soil improvement: Add compost to increase water retention</p>\n        </div>\n        \n        ${p>0?`\n        <div class="result-rainwater">\n          <h4>Rainwater Harvesting Potential:</h4>\n          <p><strong>Collectable rainwater:</strong> ${L.toFixed(0)} gallons ${d}</p>\n          <p><strong>Value:</strong> $${T.toFixed(2)} ${d}</p>\n          <p>Roof collection area: ${H.toLocaleString()} sq ft (estimated)</p>\n          <p>Payback: Rain barrels pay for themselves in ${(200/T).toFixed(1)} periods</p>\n          <p>Environmental benefit: Reduces stormwater runoff</p>\n        </div>\n        `:""}\n        \n        <div class="result-schedule">\n          <h4>Watering Schedule:</h4>\n          <p>🌅 <strong>Best time:</strong> Early morning (5-9 AM)</p>\n          <p>🕐 <strong>Frequency:</strong> ${function(e,n){return"clay"===e?n>1?"2-3 times per week (deep watering)":"1-2 times per week":"sandy"===e?n>1?"Daily light watering or every other day":"3-4 times per week":n>1?"3-4 times per week":"2-3 times per week"}(h,I)}</p>\n          <p>⏱️ <strong>Duration:</strong> ${U=f,z=I,`${{drip:Math.round(60*z),soaker:Math.round(45*z),sprinkler:Math.round(30*z),hand:Math.round(20*z),overhead:Math.round(25*z)}[U]||30} minutes per session`}</p>\n          <p>🌡️ <strong>Adjust for weather:</strong> Skip watering if rain expected within 24 hours, increase 25% during heat waves</p>\n          <p>📅 <strong>Seasonal changes:</strong> Reduce watering 50% in fall, minimal in winter, increase gradually in spring</p>\n        </div>\n        \n        <div class="result-conservation">\n          <h4>Water Conservation Tips:</h4>\n          <p>🌿 Mulch saves ${(k*M*E*52).toFixed(0)} gallons annually</p>\n          <p>🌱 Native plants can reduce water needs by 50-70%</p>\n          <p>🕐 Timer systems prevent overwatering and save 15-25%</p>\n          <p>🌧️ Rain sensors automatically skip watering when it rains</p>\n          <p>💧 Drip irrigation can save 30-50% compared to sprinklers</p>\n        </div>\n        \n        <div class="result-plant-health">\n          <h4>Plant Health Indicators:</h4>\n          <p>✅ <strong>Proper watering signs:</strong> Vibrant color, steady growth, firm stems, no wilting during cool parts of day</p>\n          <p>⚠️ <strong>Overwatering signs:</strong> Yellow leaves, fungal growth, soft stems, constantly wet soil surface</p>\n          <p>🚨 <strong>Underwatering signs:</strong> Wilting, dry/crispy leaves, stunted growth, hard/cracked soil</p>\n          <p>🧪 <strong>Soil check:</strong> Moisture 4-6" deep indicates root zone health</p>\n        </div>\n        \n        <div class="result-environmental">\n          <h4>Environmental Impact:</h4>\n          <p>🌍 Carbon footprint: ${j.toFixed(2)} kg CO₂ from water treatment</p>\n          <p>💧 Water conservation helps preserve local water resources</p>\n          <p>🌊 Efficient irrigation reduces runoff and erosion</p>\n          <p>🐛 Proper watering supports beneficial soil organisms</p>\n          <p>🌳 Healthy plants improve air quality and provide habitat</p>\n        </div>\n        \n        <div class="result-troubleshooting">\n          <h4>Common Issues & Solutions:</h4>\n          <p>🏃 <strong>Runoff:</strong> ${function(e){return"clay"===e?"Water slowly, add organic matter, consider drip irrigation":"Create small berms, use mulch to slow water movement, improve soil structure"}(h)}</p>\n          <p>🦠 <strong>Disease prevention:</strong> Water at soil level, avoid late evening watering, ensure good air circulation</p>\n          <p>💸 <strong>High water bills:</strong> Check for leaks, upgrade to efficient irrigation, increase mulch coverage</p>\n          <p>🌡️ <strong>Heat stress:</strong> Water early morning, provide afternoon shade, increase mulch thickness</p>\n          <p>❄️ <strong>Winter preparation:</strong> Drain irrigation lines, protect tender plants, reduce watering frequency</p>\n        </div>\n        \n        <div class="result-monitoring">\n          <h4>Monitoring Your Garden:</h4>\n          <p>📏 Use a rain gauge to track natural water input</p>\n          <p>🌡️ Monitor soil moisture with a probe or finger test</p>\n          <p>📱 Weather apps help predict rain and adjust schedules</p>\n          <p>📊 Keep watering logs to optimize your schedule</p>\n          <p>🎯 Adjust based on plant response and seasonal changes</p>\n        </div>\n      `})});